#!/usr/bin/env bash
# Generated by Phase: IMPLEMENT | Feature: EVOL-043
# META-ONLY: materialisation smoke of the framework's own template tree; not shipped to projects.
# materialize-synthetic.sh — SETUP --generate is LLM-driven and cannot run in CI. This script does the
# mechanical part the same way (manifest targets, placeholder resolution with sample values, framework
# tree delivered as factory-sync would) into a scratch project, then runs the governance toolchain THERE:
#
#   1. every manifest template with a target lands (unconditional entries + one stack sample)
#   2. no placeholder token survives in config JSON; every config parses
#   3. the snapshot generator produces a lite snapshot within budgets.snapshot
#   4. the one resolver prints a roll-call with every project law and family
#   5. every law (universal + project) resolves its Body: pointer and quotes the identical sentence (gate.py laws --parity)
#   6. injection budgets hold against the real producers; the retired-term ratchet is clean;
#      manifest ↔ frontmatter parity and artefact currency hold (EVOL-044); branch classes, the one diff
#      base and the surface ceiling read the project's keys — a train is protected, an over-ceiling diff is red (EVOL-045)
#   7. every hook wired in settings.json is delivered and executable; a real edit payload gets its law delivered
#
# Exit codes: 0 all green · 1 a check failed · 2 infrastructure. Set MATERIALIZE_KEEP=1 to keep the scratch tree.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
T="$ROOT/.context/templates/setup"
MANIFEST="$T/governance_versions.json"
[ -f "$MANIFEST" ] || { echo "materialize-synthetic: manifest missing" >&2; exit 2; }
command -v python3 >/dev/null || { echo "materialize-synthetic: python3 required" >&2; exit 2; }
command -v git >/dev/null || { echo "materialize-synthetic: git required" >&2; exit 2; }
export PYTHONDONTWRITEBYTECODE=1
SCRATCH=$(mktemp -d) || exit 2
[ "${MATERIALIZE_KEEP:-0}" = "1" ] || trap 'rm -rf "$SCRATCH"' EXIT
P="$SCRATCH/proj"; mkdir -p "$P"
PASS=0; FAIL=0
ok()  { PASS=$((PASS+1)); echo "  ✓ $1"; }
bad() { FAIL=$((FAIL+1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "$2" | sed 's/^/      /' | head -12; return 0; }

echo "── materialise (manifest targets + sample answers) ──"
REPORT=$(python3 - "$T" "$P" "$MANIFEST" <<'PY'
import json, re, sys, shutil
from pathlib import Path
T, P, M = Path(sys.argv[1]), Path(sys.argv[2]), Path(sys.argv[3])
m = json.loads(M.read_text())
SAMPLE = {  # one stack sample; conditionals not matching are skipped
    "backend.runtime == Python": True, "backend.runtime == Node": False, "backend.runtime == Java": False,
    "backend.runtime == C#": False, "frontend.framework == React": True,
    'ci_cd_platform == "GitHub Actions"': True, 'po_package.mode != "off"': True,
}
def cond_ok(c):
    if not c: return True
    for k, v in SAMPLE.items():
        if k in c: return v
    return "GitHub" in c or "Python" in c or "React" in c
landed, skipped = [], []
for key, e in m["templates"].items():
    if key.startswith("_") or not isinstance(e, dict): continue
    src = T / key; tgt = e.get("target")
    if not tgt or not src.is_file():
        skipped.append(key); continue
    if not cond_ok(e.get("stack_conditional")):
        skipped.append(key); continue
    if e.get("delivery") == "sync":
        skipped.append(key); continue
    dst = P / tgt; dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst); landed.append(tgt)
# the constitution template lands as the project's index
if (T / "constitution/constitution_template.md").is_file():
    (P / "docs").mkdir(exist_ok=True); shutil.copy2(T / "constitution/constitution_template.md", P / "docs/constitution.md"); landed.append("docs/constitution.md")
if (T / "setup/setup_master_template.md").is_file():
    shutil.copy2(T / "setup/setup_master_template.md", P / "docs/setup.md"); landed.append("docs/setup.md")
# placeholder resolution with sample values (the SETUP rule: quoted tokens → strings, bare numeric tokens → integers,
# {{#if}}/{{#each}} blocks keep their content)
NUM = {"MEASURE_RETENTION_DAYS": "90", "MEASURE_REPORT_INTERVAL_DAYS": "30", "SURFACE_CEILING_FILES": "3", "SURFACE_CEILING_LINES": "800"}
def resolve(text, is_json):
    if is_json:  # greenfield sample: conditional blocks are dropped whole (a kept block would leave a trailing comma)
        text = re.sub(r"[ \t]*\{\{#if[^}]*\}\}.*?\{\{/if\}\}[ \t]*\n?", "", text, flags=re.S)
    text = re.sub(r"\{\{[#/](if|each|unless)[^}]*\}\}", "", text)
    for k, v in NUM.items():
        text = text.replace("{{" + k + "}}", v)
    if is_json:
        text = re.sub(r'"\{\{[A-Z_]+\}\}"', '"sample"', text)
        text = re.sub(r"\{\{[A-Z_]+\}\}", "sample", text)
    else:
        text = re.sub(r"\{\{[A-Z_|]+\}\}", "sample", text)
        text = re.sub(r"\{\{[a-z_.]+\}\}", "sample", text)
    return text
unresolved = []
for f in P.rglob("*"):
    if not f.is_file() or f.suffix in (".png", ".jpg", ".pdf", ".zip"): continue
    try: text = f.read_text(encoding="utf-8")
    except UnicodeDecodeError: continue
    if "{{" in text:
        f.write_text(resolve(text, f.suffix == ".json"), encoding="utf-8")
    if f.suffix == ".json" and "{{" in f.read_text(encoding="utf-8"):
        unresolved.append(str(f.relative_to(P)))
print(json.dumps({"landed": len(landed), "skipped": len(skipped), "unresolved_json": unresolved}))
PY
) || { echo "materialize-synthetic: materialisation step failed" >&2; exit 2; }
echo "  $REPORT"
LANDED=$(printf '%s' "$REPORT" | python3 -c 'import json,sys; print(json.load(sys.stdin)["landed"])')
[ "$LANDED" -ge 60 ] && ok "manifest targets landed ($LANDED)" || bad "too few targets landed ($LANDED)"
UNRES=$(printf '%s' "$REPORT" | python3 -c 'import json,sys; print(",".join(json.load(sys.stdin)["unresolved_json"]))')
[ -z "$UNRES" ] && ok "no placeholder survives in config JSON" || bad "unresolved tokens in JSON: $UNRES"

# framework tree as factory-sync delivers it (skills / instructions / commands / hooks / gate reader)
mkdir -p "$P/.claude" "$P/scripts"
cp -R "$ROOT/.claude/skills" "$P/.claude/skills"; cp -R "$ROOT/.claude/instructions" "$P/.claude/instructions"; cp -R "$ROOT/.claude/commands" "$P/.claude/commands"
[ -d "$P/.claude/hooks" ] || cp -R "$T/claude/hooks" "$P/.claude/hooks"
[ -f "$P/.claude/settings.json" ] || cp "$T/claude/settings.json" "$P/.claude/settings.json"
[ -f "$P/CLAUDE.md" ] || cp "$T/claude/CLAUDE.md" "$P/CLAUDE.md"
for s in gate.py generate-governance-snapshot.sh validate-governance.sh governance-onprompt.sh governance-onedit.sh governance-oncompact.sh check-adr-constitution-sync.sh; do
  [ -f "$P/scripts/$s" ] || cp "$T/scripts/$s" "$P/scripts/$s" 2>/dev/null || true
done
[ -d "$P/scripts/gates" ] || cp -R "$T/scripts/gates" "$P/scripts/gates"
mkdir -p "$P/config"; [ -f "$P/config/coherence-context.json" ] || cp "$T/config/coherence-context.json" "$P/config/coherence-context.json"
git -C "$P" init -q && git -C "$P" add -A && git -C "$P" -c user.name=t -c user.email=t@t commit -qm scratch
for f in config/quality.json config/coherence-context.json config/protected-paths.json; do
  python3 -c "import json,sys; json.load(open('$P/$f'))" 2>/dev/null && ok "$f parses" || bad "$f does not parse"
done
grep -q '^  authoring:' "$P/docs/setup.md" && ok "docs/setup.md carries the Q29 frontmatter keys" || bad "docs/setup.md frontmatter lacks codesign.authoring"

echo "── governance toolchain in the scratch project ──"
OUT=$(cd "$P" && bash scripts/generate-governance-snapshot.sh 2>&1); RC=$?
[ "$RC" -eq 0 ] && ok "snapshot generated: $(echo "$OUT" | head -1 | sed 's/.*(//;s/)//')" || bad "snapshot generator failed (rc=$RC)" "$OUT"
grep -q '^### \[PLAW-01\]' "$P/.context/governance_snapshot.md" && ok "law index in the snapshot" || bad "law index missing from snapshot"
OUT=$(cd "$P" && python3 scripts/gate.py applicable --phase IMPLEMENT --command implement --change-type feature --format rollcall 2>&1); RC=$?
LAWS=$(printf '%s' "$OUT" | grep -oE 'ACTIVE LAWS \([0-9]+\)' | grep -oE '[0-9]+'); DCS=$(printf '%s' "$OUT" | grep -oE 'ACTIVE DCs \([0-9]+\)' | grep -oE '[0-9]+')
[ "$RC" -eq 0 ] && [ "${LAWS:-0}" -ge 26 ] && [ "${DCS:-0}" -ge 4 ] && ok "roll-call: $LAWS laws, $DCS DCs" || bad "roll-call short (laws=$LAWS dcs=$DCS rc=$RC)" "$OUT"
printf '%s' "$OUT" | grep -q 'Discovery hash:' && ok "discovery hash emitted" || bad "no discovery hash"
OUT=$(cd "$P" && python3 scripts/gate.py laws --parity 2>&1); RC=$?
[ "$RC" -eq 0 ] && ok "gate.py laws --parity: every law resolves its Body: pointer and quotes the identical sentence" || bad "law parity red in the scratch project" "$OUT"
OUT=$(cd "$P" && python3 scripts/gate.py budget 2>&1); RC=$?
[ "$RC" -eq 0 ] && ok "injection budgets hold against the real producers" || bad "budget red (rc=$RC)" "$OUT"
PS=$(printf '%s' "$OUT" | grep '| prompt_submit |' | awk -F'|' '{gsub(/ /,"",$4); print $4}'); SNAPB=$(wc -c < "$P/.context/governance_snapshot.md" | tr -d ' ')
[ "${PS:-0}" -ge "$SNAPB" ] 2>/dev/null && ok "prompt_submit worst case measured ≥ the snapshot ($PS ≥ $SNAPB B: the reload is forced)" || bad "prompt_submit worst case smaller than the snapshot ($PS < $SNAPB) — the reload is not forced" "$OUT"
PRE=$(printf '%s' "$OUT" | grep '| pre_edit |' | awk -F'|' '{gsub(/ /,"",$4); print $4}')
[ "${PRE:-0}" -gt 0 ] 2>/dev/null && ok "pre-edit delivery measured on the worst-case path ($PRE B, never 0)" || bad "pre-edit measured empty — dead delivery" "$OUT"
OUT=$(cd "$P" && printf '%s' '{"tool_input":{"file_path":"src/app/models.py"},"session_id":"smoke"}' | bash .claude/hooks/deliver-governance.sh 2>&1)
printf '%s' "$OUT" | grep -q '"additionalContext"' && printf '%s' "$OUT" | grep -q 'DC-' && ok "a real edit payload gets its defect classes delivered through the envelope" || bad "delivery hook delivered nothing for src/app/models.py" "$OUT"
OUT=$(cd "$P" && python3 scripts/gate.py retired-terms 2>&1); RC=$?
[ "$RC" -eq 0 ] && ok "retired-term ratchet clean in the materialised tree" || bad "retired terms in the materialised tree" "$OUT"
# the project manifest SETUP writes (targets keyed by template path, versions carried over) — then parity must hold
python3 - "$MANIFEST" "$P/docs/project_log/governance_versions.json" <<'PY'
import json, sys, pathlib
m = json.load(open(sys.argv[1])); out = {"framework_version": m["framework_version"], "templates": {}}
for k, e in m["templates"].items():
    if isinstance(e, dict) and e.get("target"): out["templates"][k] = {"version": e["version"], "target": e["target"]}
p = pathlib.Path(sys.argv[2]); p.parent.mkdir(parents=True, exist_ok=True); p.write_text(json.dumps(out, indent=1))
PY
OUT=$(cd "$P" && python3 scripts/gate.py manifest-parity 2>&1); RC=$?
[ "$RC" -eq 0 ] && ok "manifest ↔ frontmatter parity holds for every materialised governed file" || bad "manifest parity red in the scratch project" "$OUT"
printf '%s' "$OUT" | grep -qE 'ok \([1-9][0-9]* compared' && ok "manifest parity compared real entries ($(printf '%s' "$OUT" | grep -oE '[0-9]+ compared'))" || bad "manifest parity compared nothing (vacuous)" "$OUT"
sed -i '0,/^version: /s//version: 9.9.9\nx_drift: /' "$P/.claude/rules/architecture.md"
OUT=$(cd "$P" && python3 scripts/gate.py manifest-parity 2>&1); RC=$?
[ "$RC" -eq 1 ] && printf '%s' "$OUT" | grep -q 'architecture.md' && ok "RED: an injected frontmatter drift is caught in the scratch project" || bad "injected drift not caught (rc=$RC)" "$OUT"
sed -i '/^x_drift: /d; 0,/^version: 9.9.9/s//version: '"$(cd "$P" && python3 -c "import json;print(json.load(open('docs/project_log/governance_versions.json'))['templates']['rules/architecture.md']['version'])")"'/' "$P/.claude/rules/architecture.md"
# a real verdict on a feature branch: certified → ok; its certified file moves → STALE
git -C "$P" checkout -q -b feature/FEAT-001-smoke; mkdir -p "$P/src" "$P/docs/spec/FEAT-001/qa"; printf 'print(1)\n' > "$P/src/app.py"
git -C "$P" add -A; git -C "$P" -c user.name=t -c user.email=t@t commit -qm src; git -C "$P" update-ref refs/remotes/origin/main HEAD
CERT=$(cd "$P" && python3 scripts/gate.py certify --subject tree --paths 'src/**')
printf -- '---\nstatus: APPROVED\nverdict: APPROVED\ncertifies:\n%s\n---\n' "$CERT" > "$P/docs/spec/FEAT-001/qa/qa_report_final_20260925.md"
git -C "$P" add -A; git -C "$P" -c user.name=t -c user.email=t@t commit -qm verdict
OUT=$(cd "$P" && python3 scripts/gate.py currency 2>&1); RC=$?
[ "$RC" -eq 0 ] && ok "artefact currency: a verdict certified with gate.py certify is fresh" || bad "fresh verdict judged red (rc=$RC)" "$OUT"
printf 'print(2)\n' > "$P/src/app.py"; git -C "$P" add -A; git -C "$P" -c user.name=t -c user.email=t@t commit -qm moved
OUT=$(cd "$P" && python3 scripts/gate.py currency 2>&1); RC=$?
[ "$RC" -eq 1 ] && printf '%s' "$OUT" | grep -q 'STALE' && ok "RED: the certified file moved → the verdict is STALE" || bad "moved subject not caught (rc=$RC)" "$OUT"
# branch grammar + the one diff base + the surface ceiling (EVOL-045) on the materialised keys
OUT=$(cd "$P" && python3 scripts/gate.py surface 2>&1); RC=$?
[ "$RC" -eq 0 ] && printf '%s' "$OUT" | grep -q 'surface: ok' && ok "surface under the materialised ceiling: $OUT" || bad "surface gate wrong on a small diff (rc=$RC)" "$OUT"
for i in 1 2 3 4; do printf 'x\n' > "$P/src/f$i.py"; done; git -C "$P" add -A; git -C "$P" -c user.name=t -c user.email=t@t commit -qm wide
OUT=$(cd "$P" && python3 scripts/gate.py surface 2>&1); RC=$?
[ "$RC" -eq 1 ] && printf '%s' "$OUT" | grep -q 'exceeds the ceiling' && ok "RED: a diff over surface.ceiling_files is blocked" || bad "over-ceiling diff not caught (rc=$RC)" "$OUT"
git -C "$P" -c user.name=t -c user.email=t@t commit -q --allow-empty -m $'chore: generated\n\nSurface-Escape: generated-code'
OUT=$(cd "$P" && python3 scripts/gate.py surface 2>&1); RC=$?
[ "$RC" -eq 0 ] && printf '%s' "$OUT" | grep -q 'escape: generated-code' && ok "a Surface-Escape trailer from the closed list passes" || bad "valid escape not honoured (rc=$RC)" "$OUT"
mkdir -p "$P/docs/spec/FEAT-001"; printf '### INC-1 — x\n- **Sub-increments:**\n  - SUB-1-1: a · branch feature/FEAT-001-inc-1-x-sub-1\n' > "$P/docs/spec/FEAT-001/increment_plan.md"
OUT=$(cd "$P" && python3 scripts/gate.py branch-class --branch feature/FEAT-001-inc-1-x --protected 2>&1); RC=$?
[ "$RC" -eq 1 ] && ok "a per-increment branch with declared sub-increments is a protected train" || bad "train not protected (rc=$RC)" "$OUT"
OUT=$(cd "$P" && python3 scripts/gate.py surface --base origin/main --branch feature/FEAT-001-inc-1-x 2>&1); RC=$?
[ "$RC" -eq 0 ] && printf '%s' "$OUT" | grep -q 'train' && ok "the train's closing PR (CI shape: explicit base + head ref) is green by class" || bad "train closing PR red (rc=$RC)" "$OUT"
OUT=$(cd "$P" && python3 scripts/gate.py diff-base --branch feature/FEAT-001-inc-1-x-sub-2 2>&1); RC=$?
[ "$RC" -eq 2 ] && printf '%s' "$OUT" | grep -q 'is not on origin' && ok "a train never pushed is a fault said in plain language (push -u named)" || bad "missing train ref not said (rc=$RC)" "$OUT"
git -C "$P" update-ref refs/remotes/origin/feature/FEAT-001-inc-1-x HEAD
OUT=$(cd "$P" && python3 scripts/gate.py diff-base --branch feature/FEAT-001-inc-1-x-sub-2 2>&1); RC=$?
[ "$RC" -eq 0 ] && [ "$OUT" = "origin/feature/FEAT-001-inc-1-x" ] && ok "a sub-increment's diff base is its train" || bad "sub-increment diff base wrong (rc=$RC): $OUT"
OUT=$(cd "$P" && git checkout -q -b nonsense && python3 scripts/gate.py diff-base 2>&1); RC=$?; git -C "$P" checkout -q feature/FEAT-001-smoke
[ "$RC" -eq 1 ] && printf '%s' "$OUT" | grep -q 'matches no class' && ok "RED: an unrecognised branch name has no diff base (fail-closed)" || bad "unknown branch not red (rc=$RC)" "$OUT"
MISSING=$(cd "$P" && python3 -c "
import json; d=json.load(open('.claude/settings.json')); import os
scripts=[t for g in d['hooks'].values() for grp in g for h in grp['hooks'] for t in h['command'].split() if t.endswith('.sh')]
print(' '.join(t for t in scripts if not (os.path.isfile(t) and os.access(t, os.X_OK))))")
[ -z "$MISSING" ] && ok "every hook wired in settings.json is delivered and executable" || bad "hooks wired but not delivered/executable: $MISSING"
OUT=$(cd "$P" && bash scripts/validate-governance.sh --banner 2>&1)
printf '%s' "$OUT" | grep -q 'Governance loaded: constitution' && ok "session banner: $OUT" || bad "banner wrong" "$OUT"

echo; echo "materialize-synthetic: $PASS passed, $FAIL failed"
[ "${MATERIALIZE_KEEP:-0}" = "1" ] && echo "scratch kept at $P"
[ "$FAIL" -eq 0 ]
